// `npm run seed:voices`: the 12 synthetic voice notes (docs/seed-spec.md §11). Eleven with Amazon
// Polly (`SynthesizeSpeech`, neural, es-MX, voices Mia and Andres, native Ogg/Opus at 48 kHz) after
// checking with `DescribeVoices` that both voices exist for that engine and language; vn-09 is noise
// generated by code and encoded with ffmpeg. The operator runs it with their profile (the only AWS
// call of the seed); the files and the datasheet are committed and checked by sha256.
//
//   AWS_PROFILE=craftech-demos npm run seed:voices
//   npm run seed:voices -- --profile craftech-demos --only vn-01,vn-09
//   npm run seed:voices -- --dry-run          (plan only: no AWS call, nothing written)
//   npm run seed:voices -- --ffmpeg <path>    (instead of the ffmpeg-static binary)
import { spawn } from "node:child_process";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { DescribeVoicesCommand, PollyClient, SynthesizeSpeechCommand } from "@aws-sdk/client-polly";
import { NodeHttpHandler } from "@smithy/node-http-handler";
import ffmpegStatic from "ffmpeg-static";
import { parseFlags } from "../channels/cli-args";
import { noisePcm } from "./audio/noise";
import { oggOpusInfo } from "./audio/ogg";
import { AUDIO_DATASHEET_FILE, AudioDatasheet, POLLY_PARAMS, VOICES_GENERATOR, type VoiceEntry } from "./audio/schema";
import { type PollyVoice, SPEAKER_NAME, VOICE_NOTES, type VoiceNoteText } from "./audio/texts";
import { sha256Hex, stableJson } from "./photos/prng";

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const REGION = "us-east-1";
const FAKE_TRANSCRIPT_CONFIDENCE = 0.93;
const PAUSE_BETWEEN_READINGS = '<break time="2s"/>';

export function voiceFile(voiceId: string): string {
  return `scripts/seed/audio/${voiceId}.ogg`;
}

function escapeSsml(text: string): string {
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");
}

/** Text or SSML sent to Polly: a repeated reading goes as SSML, a little slower, with a pause between readings. */
export function pollyInput(note: VoiceNoteText): { text: string; textType: "text" | "ssml" } {
  if (note.repeat === 1) return { text: note.text, textType: "text" };
  const readings = Array.from({ length: note.repeat }, () => escapeSsml(note.text)).join(PAUSE_BETWEEN_READINGS);
  return { text: `<speak><prosody rate="90%">${readings}</prosody></speak>`, textType: "ssml" };
}

/** What the LF Transcribe fake returns: the spoken words, or nothing for the noise. */
export function fakeTranscript(note: VoiceNoteText): VoiceEntry["transcript"] {
  if (note.voice === null) return { text: "", confidence: 0 };
  return { text: Array.from({ length: note.repeat }, () => note.text).join(" "), confidence: FAKE_TRANSCRIPT_CONFIDENCE };
}

function pollyClient(profile: string): PollyClient {
  return new PollyClient({
    region: REGION,
    profile,
    maxAttempts: 4,
    requestHandler: new NodeHttpHandler({ connectionTimeout: 5_000, requestTimeout: 60_000 }),
  });
}

async function checkVoices(client: PollyClient): Promise<void> {
  const response = await client.send(new DescribeVoicesCommand({ LanguageCode: POLLY_PARAMS.languageCode, Engine: POLLY_PARAMS.engine }));
  const available = new Set((response.Voices ?? []).map((voice) => voice.Id));
  const needed: PollyVoice[] = ["Mia", "Andres"];
  const missing = needed.filter((voice) => !available.has(voice));
  if (missing.length > 0) throw new Error(`Polly has no ${POLLY_PARAMS.engine} ${POLLY_PARAMS.languageCode} voice ${missing.join(", ")}`);
}

async function synthesize(client: PollyClient, note: VoiceNoteText, voice: PollyVoice): Promise<Uint8Array> {
  const input = pollyInput(note);
  const response = await client.send(
    new SynthesizeSpeechCommand({
      Engine: POLLY_PARAMS.engine,
      LanguageCode: POLLY_PARAMS.languageCode,
      VoiceId: voice,
      OutputFormat: POLLY_PARAMS.outputFormat,
      SampleRate: POLLY_PARAMS.sampleRate,
      Text: input.text,
      TextType: input.textType,
    }),
  );
  if (response.AudioStream === undefined) throw new Error(`${note.voiceId}: Polly returned no audio`);
  return response.AudioStream.transformToByteArray();
}

/** PCM → Ogg/Opus with ffmpeg, bit-exact (no random stream serial, no encoder tag). */
function encodeOpus(ffmpeg: string, pcm: Buffer): Promise<Buffer> {
  const args = ["-hide_banner", "-loglevel", "error", "-f", "s16le", "-ar", "48000", "-ac", "1", "-i", "pipe:0"];
  args.push("-c:a", "libopus", "-b:a", "32k", "-map_metadata", "-1", "-fflags", "+bitexact", "-flags:a", "+bitexact", "-f", "ogg", "pipe:1");
  return new Promise((resolvePromise, reject) => {
    const child = spawn(ffmpeg, args, { stdio: ["pipe", "pipe", "pipe"] });
    const out: Buffer[] = [];
    const err: Buffer[] = [];
    const timer = setTimeout(() => child.kill("SIGKILL"), 60_000);
    child.stdout.on("data", (chunk: Buffer) => out.push(chunk));
    child.stderr.on("data", (chunk: Buffer) => err.push(chunk));
    child.on("error", reject);
    child.on("close", (code) => {
      clearTimeout(timer);
      if (code === 0) resolvePromise(Buffer.concat(out));
      else reject(new Error(`ffmpeg exited with ${code}: ${Buffer.concat(err).toString("utf8").slice(0, 500)}`));
    });
    child.stdin.end(pcm);
  });
}

function entryFor(note: VoiceNoteText, bytes: Uint8Array, source: Pick<VoiceEntry, "source" | "polly" | "code">): VoiceEntry {
  const info = oggOpusInfo(bytes);
  if (info.channels !== 1) throw new Error(`${note.voiceId}: ${info.channels} channels, expected mono`);
  const durationSec = Math.round(info.durationSec * 1000) / 1000;
  if (durationSec < note.minDurationSec || (note.maxDurationSec !== null && durationSec > note.maxDurationSec)) {
    throw new Error(`${note.voiceId}: ${durationSec} s is outside [${note.minDurationSec}, ${note.maxDurationSec ?? "∞"}]`);
  }
  return {
    voiceId: note.voiceId,
    file: voiceFile(note.voiceId),
    mime: "audio/ogg",
    sha256: sha256Hex(bytes),
    bytes: bytes.length,
    durationSec,
    channels: 1,
    ...source,
    speaker: note.voice === null ? null : SPEAKER_NAME[note.voice],
    text: note.text,
    repeat: note.repeat,
    transcript: fakeTranscript(note),
    use: note.use,
    flows: [...note.flows],
  };
}

function previousEntries(): Map<string, VoiceEntry> {
  const path = join(REPO_ROOT, AUDIO_DATASHEET_FILE);
  if (!existsSync(path)) return new Map();
  return new Map(AudioDatasheet.parse(JSON.parse(readFileSync(path, "utf8"))).notes.map((note) => [note.voiceId, note]));
}

async function main(): Promise<void> {
  let profile = process.env.AWS_PROFILE ?? "craftech-demos";
  let ffmpeg = ffmpegStatic ?? "ffmpeg";
  let only: Set<string> | undefined;
  let dryRun = false;
  parseFlags(process.argv.slice(2), {
    "--profile": (value) => {
      profile = value();
    },
    "--ffmpeg": (value) => {
      ffmpeg = value();
    },
    "--only": (value) => {
      only = new Set(value().split(","));
    },
    "--dry-run": () => {
      dryRun = true;
    },
  });
  const selected = VOICE_NOTES.filter((note) => only === undefined || only.has(note.voiceId));
  if (dryRun) {
    for (const note of selected) console.log(`${note.voiceId}  ${note.voice ?? "code (ffmpeg)"}  ${pollyInput(note).textType}  ${note.use}`);
    return;
  }
  const previous = previousEntries();
  const client = selected.some((note) => note.voice !== null) ? pollyClient(profile) : undefined;
  if (client !== undefined) await checkVoices(client);
  for (const note of selected) {
    let bytes: Uint8Array;
    let source: Pick<VoiceEntry, "source" | "polly" | "code">;
    if (note.voice === null) {
      const pcm = noisePcm();
      bytes = await encodeOpus(ffmpeg, pcm);
      source = { source: "code", polly: null, code: { generator: "scripts/seed/audio/noise.ts", seed: 20260926, pcmSha256: sha256Hex(pcm), encoder: "ffmpeg libopus 32 kb/s, bitexact" } };
    } else {
      if (client === undefined) throw new Error("no Polly client");
      bytes = await synthesize(client, note, note.voice);
      source = { source: "polly", polly: { ...POLLY_PARAMS, voiceId: note.voice, textType: pollyInput(note).textType }, code: null };
    }
    const entry = entryFor(note, bytes, source);
    writeFileSync(join(REPO_ROOT, entry.file), bytes);
    previous.set(note.voiceId, entry);
    console.log(`${note.voiceId}: ${entry.durationSec} s, ${entry.bytes} bytes`);
  }
  const notes = VOICE_NOTES.map((note) => previous.get(note.voiceId)).filter((entry): entry is VoiceEntry => entry !== undefined);
  const datasheet = AudioDatasheet.parse({
    generator: VOICES_GENERATOR,
    generatorVersion: "1.0.0",
    seed: 20260926,
    region: REGION,
    origin: "Amazon Polly es-MX neural voices (Mia, Andres) and noise generated by scripts/seed/audio/noise.ts; seed 20260926",
    notes,
  });
  writeFileSync(join(REPO_ROOT, AUDIO_DATASHEET_FILE), stableJson(datasheet));
  console.log(`seed:voices: ${selected.length} note(s) written; the datasheet lists ${notes.length} of ${VOICE_NOTES.length}.`);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  await main();
}
